/// <summary>
/// Class is used to make copy of <c>GUPPriceTermJournalTrans</c> records. Should be called from form GUPPriceTermJournalTrans.
/// </summary>
final class GUPPriceTermJournalTransCopy
{
    FormDataSource gupPriceTermJournalTrans_ds;

    #OCCRetryCount

}

Method.Source:
private void run()
{
    GUPPriceTermJournalTrans    gupPriceTermJournalTransNew;
    MultiSelectionHelper        selectionHelper = MultiSelectionHelper::construct();

    selectionHelper.parmDataSource(gupPriceTermJournalTrans_ds);

    try
    {
        ttsbegin;

        GUPPriceTermJournalTrans gupPriceTermJournalTransOrig = selectionHelper.getFirst();
        while (gupPriceTermJournalTransOrig)
        {
            gupPriceTermJournalTransNew.clear();
            gupPriceTermJournalTransNew.initfromGUPPriceTermJournalTrans(gupPriceTermJournalTransOrig);
            gupPriceTermJournalTransNew.PricingRule = GUPPricingRule::find(gupPriceTermJournalTransOrig.PricingRule).copy().RecId;
            gupPriceTermJournalTransNew.insert();

            gupPriceTermJournalTransOrig = selectionHelper.getNext();
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private FormDataSource formDataSource(FormDataSource _gupPriceTermJournalTrans_ds = gupPriceTermJournalTrans_ds)
{
    gupPriceTermJournalTrans_ds = _gupPriceTermJournalTrans_ds;

    return gupPriceTermJournalTrans_ds;
}

public static void main(Args _args)
{
    GUPPriceTermJournalTransCopy gupPriceTermJournalTransCopy = new GUPPriceTermJournalTransCopy();

    if (_args && _args.record() && _args.record().TableId == tableNum(GUPPriceTermJournalTrans))
    {
        Object gupPriceTermJournalTrans_ds = FormDataUtil::getFormDataSource(_args.record());

        gupPriceTermJournalTransCopy.formDataSource(gupPriceTermJournalTrans_ds);
        gupPriceTermJournalTransCopy.run();

        if (gupPriceTermJournalTrans_ds)
        {
            gupPriceTermJournalTrans_ds.executeQuery();
        }
    }
    else
        throw error(strFmt("@SYS27147", new DictClass(classIdGet(GUPPriceTermJournalTransCopy)).name()));
}
